using Microsoft.Dynamics.BusinessPlatform.SharedTypes;
using Microsoft.Dynamics.ApplicationFoundation.DIXF.Instrumentation;

/// <summary>
/// Contains helpers for form logic in DMF.
/// </summary>
class METDMFFormUtil
{
}

Method.Source:
/// <summary>
/// Build the query range based on the execution history date filter.
/// </summary>
/// <param name = "_source">The form data source for the query.</param>
/// <param name = "_selection">The execution history filter to apply.</param>
/// <returns>The query build range with range applied.</returns>
[InternalUseOnlyAttribute]
public static QueryBuildRange buildRangeByExecutionHistoryDateFilter(QueryBuildDataSource _source, DMFExecutionHistoryDateFilterOptions _selection)
{
    utcdatetime filterDateTime;

    QueryBuildRange queryBuildRange = SysQuery::findOrCreateRange(_source, fieldNum(DMFExecution, CreatedDateTime));

    if(_selection == DMFExecutionHistoryDateFilterOptions::All)
    {
        queryBuildRange.value(SysQuery::valueUnlimited());
    }
    else
    {
        switch(_selection)
        {
            case DMFExecutionHistoryDateFilterOptions::PastDay:
                filterDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -1);
                break;

            case DMFExecutionHistoryDateFilterOptions::Past3Days:
                filterDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -3);
                break;

            case DMFExecutionHistoryDateFilterOptions::PastWeek:
                filterDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -7);
                break;

            case DMFExecutionHistoryDateFilterOptions::PastMonth:
                filterDateTime = DateTimeUtil::addMonths(DateTimeUtil::utcNow(), -1);
                break;

            case DMFExecutionHistoryDateFilterOptions::Past3Months:
                filterDateTime = DateTimeUtil::addMonths(DateTimeUtil::utcNow(), -3);
                break;

            case DMFExecutionHistoryDateFilterOptions::Past6Months:
                filterDateTime = DateTimeUtil::addMonths(DateTimeUtil::utcNow(), -6);
                break;

            default:
                // Default: Last week to match selection on the standard view of workspace
                filterDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -7);
                break;
        }
        queryBuildRange.value(strFmt(' > %1', datetime2Str(filterDateTime)));
    }

    return queryBuildRange;
}

/// <summary>
/// Creates the query value for a given operation type on the workspace.
/// </summary>
/// <param name = "_type">The <c>DMFOperationType</c> type.</param>
/// <returns>The query value.</returns>
[InternalUseOnlyAttribute]
public static str getQueryValueForOperationType(DMFOperationType _type)
{
    str result;

    if(_type == DMFOperationType::All)
    {
        result = SysQuery::valueUnlimited();
    }
    else
    {
        result = queryValue(_type);
    }

    return result;
}

/// <summary>
/// Creates the query value for a given project category on the workspace.
/// </summary>
/// <param name = "_category">The <c>DMFProjectCategory</c> type.</param>
/// <returns>The query value.</returns>
[InternalUseOnlyAttribute]
public static str getQueryValueForProjectCategory(DMFProjectCategory _category)
{
    str result;

    if(_category == DMFProjectCategory::Project)
    {
        result = SysQuery::valueUnlimited();
    }
    else
    {
        result = queryValue(_category);
    }

    return result;
}

/// <summary>
/// Sets a filter on the definition group by operation type.
/// </summary>
/// <param name = "_formDataSource">The datasource for the form to filter.</param>
/// <returns>The query range with filter applied.</returns>
[InternalUseOnlyAttribute]
public static QueryBuildRange setDataProjectFilterRange(QueryBuildDataSource _formDataSource)
{
    if (!_formDataSource)
    {
        throw Exception::FunctionArgument;
    }

    _formDataSource.addOrderByField(fieldNum(DMFDefinitionGroup, CreatedDateTime), SortOrder::Descending);
    QueryBuildRange dataProjectFilterRange = SysQuery::findOrCreateRange(_formDataSource, fieldNum(DMFDefinitionGroup, OperationType));

    return dataProjectFilterRange;
}

/// <summary>
/// Sets a filter on the definition group by legal entity.
/// </summary>
/// <param name = "_query">The query to add the filter to.</param>
[InternalUseOnlyAttribute]
public static void setDataSourceFilterByLegalEntity(Query _query)
{
    QueryBuildDataSource qbd, qbds;

    if (!_query)
    {
        throw Exception::FunctionArgument;
    }

    // Set query to filter data projects on legal entity.
    qbd = _query.dataSourceTable(tableNum(DMFDefinitionGroup));

    if (qbd)
    {
        qbds = qbd.addDataSource(tableNum(DMFDefinitionGroupDataArea));
        qbds.joinMode(JoinMode::ExistsJoin);
        qbds.relations(true);
        qbds.addRange(fieldNum(DMFDefinitionGroupDataArea,DataArea)).value(
            strFmt('((%1.%2 == "%3") || (%1.%2 == "%4"))',
                qbds.name(),
                fieldStr(DMFDefinitionGroupDataArea,DataArea),
                curExt(),
                ''));
    }
    else
    {
        throw error("@DMF776");
    }
}

/// <summary>
/// Return the execution company context.
/// </summary>
/// <param name = "_executionId">The execution job.</param>
/// <returns>The execution company, if any.</returns>
[InternalUseOnlyAttribute]
public static str executionCompany(DMFExecutionId _executionId)
{
    DMFDefinitionGroupExecution definitionGroupExecution;

    select firstonly1 Company, EndDateTime, ReRun, ExecutionId from definitionGroupExecution
        order by definitionGroupExecution.EndDateTime desc
        where definitionGroupExecution.ExecutionId == _executionId &&
            definitionGroupExecution.ReRun == NoYes::Yes;

    if(!definitionGroupExecution)
    {
        select firstonly1 Company, EndDateTime, ExecutionId from definitionGroupExecution
            order by definitionGroupExecution.EndDateTime desc
            where definitionGroupExecution.ExecutionId == _executionId;
    }

    return definitionGroupExecution ? definitionGroupExecution.Company : '';
}
